using System.Collections;
using System.Collections.Concurrent;
using System.Collections.Frozen;
using System.Collections.Immutable;
using System.Collections.ObjectModel;
using LuminPack;

namespace LuminPackUnitTest;

// Each method below spells every collection family with concrete types, because a generic helper would reach the registration-only
// generic fallback instead of the generated concrete operations under test. The family table is identical for every element type.
// Keep helper arguments and serializer lambda parameters explicit: otherwise the compiler repeatedly infers the same
// payload across hundreds of overloaded serializer candidates while binding each multi-lambda Check call.
public partial class ReuseFreshParityTest
{

